+func TestCurrentWatchExecutableUsesItsSpawnedPathInsteadOfSetupManifest(t *testing.T) {
+	home := t.TempDir()
+	installed := filepath.Join(t.TempDir(), "manifest-posse")
+	binary, err := os.Executable()
+	if err != nil {
+		t.Fatal(err)
+	}
+	contents, err := os.ReadFile(binary)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := os.WriteFile(installed, contents, 0o700); err != nil {
+		t.Fatal(err)
+	}
+	if err := writeSetupManifest(filepath.Join(home, setupManifestName), setupManifest{Binary: installed}); err != nil {
+		t.Fatal(err)
+	}
+	previousVerifier := watchExecutableVerifier
