244: func watchExecutableVersion(path string) string {
245: 	info, err := buildinfo.ReadFile(path)
246: 	if err != nil {
247: 		return "unknown"
248: 	}
249: 	for _, setting := range info.Settings {
250: 		if setting.Key != "-ldflags" {
251: 			continue
252: 		}
253: 		fields := strings.Fields(setting.Value)
254: 		for index := 0; index < len(fields); index++ {
255: 			value := fields[index]
256: 			if value == "-X" && index+1 < len(fields) {
257: 				index++
258: 				value = fields[index]
259: 			} else {
260: 				value = strings.TrimPrefix(value, "-X")
261: 			}
262: 			key, version, found := strings.Cut(value, "=")
263: 			if found && key == "main.version" && version != "" {
264: 				return version
265: 			}
266: 		}
267: 	}
268: 	return "unknown"
269: }
