1248: 	if err != nil {
1249: 		return err
1250: 	}
1251: 	marker := watchReexecMarker(home, os.Getpid())
1252: 	requested := false
1253: 	if _, err := os.Stat(marker); err == nil {
1254: 		requested = true
1255: 	} else if !errors.Is(err, os.ErrNotExist) {
1256: 		return err
1257: 	}
1258: 	spawned, spawnedOK := watchReexecExecutable(home, watch)
1259: 	running, runningOK := inspectWatchExecutable(os.Getpid())
1260: 	changed := false
1261: 	if spawnedOK {
1262: 		if watch != nil {
1263: 			changed = watchExecutableChangedFromRuntime(spawned, watch)
1264: 		} else if runningOK {
1265: 			changed = watchExecutableChanged(spawned, running)
1266: 		}
1267: 	}
1268: 	if changed {
1269: 		requested = true
1270: 	}
1271: 	if !requested {
1272: 		return nil
1273: 	}
1274: 	if !spawnedOK {
1275: 		return fmt.Errorf("cannot verify the spawned Posse executable")
1276: 	}
1277: 	if err := os.Remove(marker); err != nil && !errors.Is(err, os.ErrNotExist) {
1278: 		return err
1279: 	}
1280: 	args := watchReexecArguments(os.Args)
1281: 	if len(args) == 0 {
1282: 		args = []string{spawned.Path}
1283: 	} else {
1284: 		args[0] = spawned.Path
1285: 	}
1286: 	execProcess := syscall.Exec
1287: 	if s.reexecUpdate != nil {
1288: 		execProcess = s.reexecUpdate
1289: 	}
1290: 	if err := execProcess(spawned.Path, args, os.Environ()); err != nil {
1291: 		return fmt.Errorf("re-exec updated Watch: %w", err)
1292: 	}
1293: 	return errors.New("watch re-exec returned unexpectedly")
1294: }
