		if stored != nil {
			if _, err := db.RaiseWatchRuntimeFailure(ctx, project.ID, state.Token, watchRuntimeFailureSummary(project, reason), currentTime()); err != nil {
				return err
			}
			if err := stopStoredWatchRuntime(ctx, home, *stored); err != nil {
