func stopParkedWatchSystemd(ctx *axi.Context, home string, project store.Project, watch *store.WatchRuntime) {
	if watch == nil || !systemdWatchUnitLoaded(ctx.Context, home, project.ID) {
		return
	}
	if err := stopSystemdWatchNoBlock(ctx.Context, home, project.ID); err != nil {
		fmt.Fprintf(ctx.ErrOut, "Stop parked Project Watch for %s: %v\n", project.Name, err)
	}
}

func (s *Service) runWatchLoop(ctx *axi.Context, db *store.DB, project store.Project, timeout time.Duration, stopSignals <-chan os.Signal, watch *store.WatchRuntime) error {
	loopCtx := ctx.Context
	if watch != nil {
		stopHeartbeat := startWatchRuntimeHeartbeat(loopCtx, db, project.ID, *watch, func(err error) {
			fmt.Fprintf(ctx.ErrOut, "Watch progress heartbeat failed for %s: %v\n", project.Name, err)
		})
		defer stopHeartbeat()
		progress := &watchProgressReporter{heartbeat: func() {
			heartbeatCtx, cancel := context.WithTimeout(loopCtx, time.Second)
			defer cancel()
			if _, err := db.HeartbeatWatchRuntime(heartbeatCtx, project.ID, watch.PID, watch.Token, currentTime()); err != nil {
				fmt.Fprintf(ctx.ErrOut, "Watch progress heartbeat failed for %s: %v\n", project.Name, err)
			}
		}}
		loopCtx = withWatchProgress(loopCtx, progress.Report)
	}
	defer func() {
		s.cancelWatchMaintenance()
		if !s.waitForWatchMaintenance(4 * time.Second) {
			fmt.Fprintln(ctx.ErrOut, "Watch maintenance shutdown timed out; unfinished poll claims will expire")
		}
	}()
	deadline := time.Time{}
	if timeout > 0 {
		deadline = time.Now().Add(timeout)
	}
	home, err := s.homePath()
	if err != nil {
		return err
	}
	lastFailures := map[string]string{}
	lastLeadReceiverCheck := time.Time{}
	servedPass := readWatchPassToken(watchPassDonePath(home, project))
	for {
		passRequest := readWatchPassToken(watchPassRequestPath(home, project))
		if watch != nil {
			ok, err := db.HeartbeatWatchRuntime(loopCtx, project.ID, watch.PID, watch.Token, currentTime())
			if err != nil {
				fmt.Fprintf(ctx.ErrOut, "Watch heartbeat failed for %s: %v\n", project.Name, err)
			} else if !ok {
				return nil
			} else if !s.watchMaintenanceInFlight() {
				if err := s.reexecWatchIfUpdated(project.ID, watch); err != nil {
					fmt.Fprintf(ctx.ErrOut, "Watch re-exec check failed for %s: %v\n", project.Name, err)
				}
			}
		}
		select {
		case sig := <-stopSignals:
			if sig == syscall.SIGTERM {
				return s.reportWatchStopped(ctx, project, true)
			}
		default:
		}
		fresh, err := db.ProjectByID(loopCtx, project.ID)
		if err != nil {
			return err
		}
		if fresh.IsDown() || fresh.IsParked() || fresh.Root != project.Root {
			if fresh.IsParked() {
				stopParkedWatchSystemd(ctx, home, project, watch)
			}
			return nil
		}
		workspaceMissing := fresh.HerdrWorkspaceID != ""
		snapshot, snapshotErr := s.snapshot(loopCtx)
		if snapshotErr == nil {
			for _, workspace := range snapshot.Workspaces {
				if workspace.WorkspaceID == fresh.HerdrWorkspaceID {
					workspaceMissing = false
					break
				}
			}
		}
		_, blocked, err := s.prepareProjectWatchObservation(loopCtx, db, fresh)
		trackWatchReconcileBlock(ctx, db, fresh, blocked)
		if observed, readErr := db.ProjectByID(loopCtx, project.ID); readErr == nil && observed.IsParked() {
			stopParkedWatchSystemd(ctx, home, project, watch)
			return nil
		}
		if err != nil && !errors.Is(err, errRecoveryHeld) && !errors.Is(err, errRecoveryDeferred) && !isHerdrUnavailable(err) {
			recordWatchFailure(ctx, db, project.ID, lastFailures, "reconcile", err)
		}
		if err := s.maintainProjectWatch(loopCtx, db, fresh); err != nil {
			recordWatchFailure(ctx, db, project.ID, lastFailures, "maintenance", err)
		}
		if lastLeadReceiverCheck.IsZero() || time.Since(lastLeadReceiverCheck) >= time.Minute {
			if !workspaceMissing {
				if err := s.monitorLeadReceiver(loopCtx, db, fresh); err != nil && !isHerdrUnavailable(err) {
					fmt.Fprintf(ctx.ErrOut, "Lead receiver check failed for %s: %v\n", project.Name, err)
				}
				if err := s.deliverNotices(loopCtx, db, fresh); err != nil && !isHerdrUnavailable(err) {
					fmt.Fprintf(ctx.ErrOut, "Notice alert delivery failed for %s: %v\n", project.Name, err)
				}
			}
			lastLeadReceiverCheck = time.Now()
		}
		if passRequest != "" && passRequest != servedPass {
			if err := writeFile(watchPassDonePath(home, project), []byte(passRequest+"\n")); err != nil {
				fmt.Fprintf(ctx.ErrOut, "Watch pass completion record failed for %s: %v\n", project.Name, err)
			}
			servedPass = passRequest
		}
		if !deadline.IsZero() && !time.Now().Before(deadline) {
			return nil
		}
		sig, err := waitForWatchPass(ctx.Context, home, project, servedPass, stopSignals)
		if err != nil {
			return err
		}
		if sig == syscall.SIGTERM {
			return s.reportWatchStopped(ctx, project, true)
		}
		if sig == nil && watch == nil {
			if err := s.handleLeadWatchUpdate(ctx, project); err != nil {
				return err
			}
		}
	}
}

