1301: 			if index+1 < len(original) {
1302: 				index++
1303: 			}
1304: 			continue
1305: 		}
1306: 		if strings.HasPrefix(arg, "--ack=") || strings.HasPrefix(arg, "--requeue=") {
1307: 			continue
1308: 		}
1309: 		args = append(args, arg)
1310: 	}
1311: 	return args
1312: }
